template:
% 参数由系统自动注入；平行四边形：对边平行且相等
% 视觉归一化：把较长的一边缩放到 6 个坐标单位，线宽字体不缩放；装饰尺寸已做 figscale 补偿
\pgfmathsetmacro{\Dx}{\ad*cos(\anglea)}
\pgfmathsetmacro{\Dy}{\ad*sin(\anglea)}
\pgfmathsetmacro{\figscale}{6 / max(\ab, \ad)}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \coordinate (A) at (0,0);
  \coordinate (B) at (\ab,0);
  \coordinate (C) at (\ab+\Dx,\Dy);
  \coordinate (D) at (\Dx,\Dy);
  \draw[thick] (A) -- (B) -- (C) -- (D) -- cycle;
  % D 向直线 AB 的垂线（虚线；钝角时垂足在 AB 延长线上，延长线段自动补画到垂足）
  \ifnum\showheightd>0
    \ifdim\Dx pt<0 pt
      \draw[dashed] (0,0) -- (\Dx,0);
    \else
      \ifdim\Dx pt>\ab pt
        \draw[dashed] (\ab,0) -- (\Dx,0);
      \fi
    \fi
    \draw[dashed] (D) -- (\Dx,0);
    \fill (\Dx,0) circle [radius=1.6pt];
    \node[below=3pt] at (\Dx,0) {$\footlabel$};
    \pgfmathsetmacro{\rmh}{min(0.3/\figscale, \Dy*0.2)}
    % 直角记号画在竖线两侧中有水平线段的一侧（钝角垂足在 A 左侧延长线上时朝右，即图形内侧）
    \ifdim\Dx pt<\rmh pt
      \draw[thick] (\Dx,\rmh) -- (\Dx+\rmh,\rmh) -- (\Dx+\rmh,0);
    \else
      \draw[thick] (\Dx-\rmh,0) -- (\Dx-\rmh,\rmh) -- (\Dx,\rmh);
    \fi
  \fi
  % C 向直线 AB 的垂线（虚线；钝角时垂足在 AB 延长线上，延长线段自动补画到垂足）
  \ifnum\showheightc>0
    \pgfmathsetmacro{\Cx}{\ab+\Dx}
    \ifdim\Cx pt<0 pt
      \draw[dashed] (0,0) -- (\Cx,0);
    \else
      \ifdim\Cx pt>\ab pt
        \draw[dashed] (\ab,0) -- (\Cx,0);
      \fi
    \fi
    \draw[dashed] (C) -- (\Cx,0);
    \fill (\Cx,0) circle [radius=1.6pt];
    \node[below=3pt] at (\Cx,0) {$\cfootlabel$};
    \pgfmathsetmacro{\rmc}{min(0.3/\figscale, \Dy*0.2)}
    % 直角记号画在竖线两侧中有水平线段的一侧（钝角垂足在 A 左侧延长线上时朝右，即图形内侧）
    \ifdim\Cx pt<\rmc pt
      \draw[thick] (\Cx,\rmc) -- (\Cx+\rmc,\rmc) -- (\Cx+\rmc,0);
    \else
      \draw[thick] (\Cx-\rmc,0) -- (\Cx-\rmc,\rmc) -- (\Cx,\rmc);
    \fi
  \fi
  % 对角线 AC
  \ifnum\showdiagac>0
    \draw[thick] (A) -- (C);
  \fi
  % 对角线 BD
  \ifnum\showdiagbd>0
    \draw[thick] (B) -- (D);
  \fi
  % 对角线交点：两线同开时画小圆点并标 O（O 为 AC 中点；标签沿两对角线较宽夹角的角平分线偏移以避开两条线，偏移量做 figscale 补偿）
  \ifnum\showdiagac>0
    \ifnum\showdiagbd>0
      \pgfmathsetmacro{\Ox}{(\ab+\Dx)/2}
      \pgfmathsetmacro{\Oy}{\Dy/2}
      \fill (\Ox,\Oy) circle [radius=1.6pt];
      \pgfmathsetmacro{\uax}{(\ab+\Dx)/sqrt((\ab+\Dx)^2+\Dy*\Dy)}
      \pgfmathsetmacro{\uay}{\Dy/sqrt((\ab+\Dx)^2+\Dy*\Dy)}
      \pgfmathsetmacro{\ubx}{(\Dx-\ab)/sqrt((\Dx-\ab)^2+\Dy*\Dy)}
      \pgfmathsetmacro{\uby}{\Dy/sqrt((\Dx-\ab)^2+\Dy*\Dy)}
      \pgfmathsetmacro{\pax}{\uax+\ubx}
      \pgfmathsetmacro{\pay}{\uay+\uby}
      \pgfmathsetmacro{\pbx}{\uax-\ubx}
      \pgfmathsetmacro{\pby}{\uay-\uby}
      \pgfmathsetmacro{\pal}{sqrt(\pax*\pax+\pay*\pay)}
      \pgfmathsetmacro{\pbl}{sqrt(\pbx*\pbx+\pby*\pby)}
      \ifdim\pal pt<\pbl pt
        \pgfmathsetmacro{\wx}{\pax/\pal}
        \pgfmathsetmacro{\wy}{\pay/\pal}
      \else
        \pgfmathsetmacro{\wx}{\pbx/\pbl}
        \pgfmathsetmacro{\wy}{\pby/\pbl}
      \fi
      \ifdim\wy pt<0 pt
        \pgfmathsetmacro{\wx}{-\wx}
        \pgfmathsetmacro{\wy}{-\wy}
      \fi
      \pgfmathsetmacro{\roff}{0.32/\figscale}
      \node at (\Ox+\roff*\wx, \Oy+\roff*\wy) {$O$};
    \fi
  \fi
  % 顶点标签
  \node[below left=3pt] at (A) {$A$};
  \node[below right=3pt] at (B) {$B$};
  \node[above right=3pt] at (C) {$C$};
  \node[above left=3pt] at (D) {$D$};
\end{tikzpicture}
